/// Registered customer accounts with email/password authentication
/// credentials. This is the core customer identity table that authentication
/// sessions, password resets, and email verifications reference. Profile
/// information (display name, phone number) is stored in the separate {@link
/// shopping_mall_customer_profiles} table. Customers can delete their
/// accounts, which preserves orders and reviews for legal and seller record
/// purposes while removing profile data.
///
/// @namespace authorization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's email address used for authentication and communication. Must
  /// be unique across all customers.
  email String

  /// Bcrypt hashed password for authentication. Never store plain text
  /// passwords.
  password_hash String

  /// Timestamp when the customer account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was soft deleted. Null means account
  /// is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions shopping_mall_customer_sessions[]
  passwordResets shopping_mall_customer_password_resets[]
  emailVerifications shopping_mall_customer_email_verifications[]
  profile shopping_mall_customer_profiles?
  customerProfileSnapshots shopping_mall_customer_profile_snapshots[]
  addresses shopping_mall_addresses[]
  wishlistItems shopping_mall_wishlist_items[]
  cart shopping_mall_carts?
  orders shopping_mall_orders[]
  reviews shopping_mall_reviews[]
  cancellationRequests shopping_mall_cancellation_requests[]
  refundRequests shopping_mall_refund_requests[]
  adminPromotionRequests shopping_mall_admin_promotion_request_of_customers[]

  //----
  // INDEXES
  //----
  @@unique([email])
}

