  /// Seller's {@link shopping_mall_sellers.id}. Unique constraint enforces 1:1
  /// relationship.
  seller_id String @db.Uuid

  /// Public-facing shop name displayed to customers.
  shop_name String

  /// Shop description providing business details to customers.
  description String

  /// Shop logo image URL for brand identification.
  logo_image_uri String @db.VarChar(80000)

  /// Timestamp when the profile was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the profile was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the profile was soft deleted (null if active).
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  seller shopping_mall_sellers @relation(fields: [seller_id], references: [id], onDelete: Cascade)

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  snapshots shopping_mall_seller_profile_snapshots[]

  //----
  // INDEXES
  //----
  @@unique([seller_id])
  @@index([shop_name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

