import { authorize_customer_join } from "../../../authorize/authorize_customer_join";
import { authorize_customer_login } from "../../../authorize/authorize_customer_login";
import { authorize_customer_refresh } from "../../../authorize/authorize_customer_refresh";

/**
 * Test customer refresh token success path.
 * 1. Register a new customer account to establish initial authentication
 * 2. Extract refresh token from initial authentication response
 * 3. Create new connection for refresh operation
 * 4. Call refresh endpoint with the refresh token using utility function
 * 5. Verify new tokens are returned with proper structure and expiration
 * 6. Confirm new refresh token differs from old one (token rotation strategy)
 * 7. Verify customer identity (id, email, profile) remains consistent
 * 8. Validate new access token format is valid JWT structure
 */
export async function test_api_customer_refresh_token_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register new customer and get initial authentication tokens
  const joinResult = await authorize_customer_join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(joinResult);
  // 2. Store original refresh token for rotation comparison
  const originalRefreshToken = joinResult.token.refresh;
  // 3. Create new connection for refresh operation (connection isolation)
  const refreshConnection: api.IConnection = { host: connection.host };
  // 4. Call refresh endpoint using utility function with refresh token
  const refreshResult = await authorize_customer_refresh(refreshConnection, {
    body: {
      refresh: originalRefreshToken,
    } satisfies IShoppingMallCustomer.IRefresh,
  });
  typia.assert(refreshResult);
  // 5. Verify new tokens are returned with proper structure
  TestValidator.predicate(
    "new access token exists",
    refreshResult.token.access.length > 0,
  );
  TestValidator.predicate(
    "new refresh token exists",
    refreshResult.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "access token has expiration timestamp",
    refreshResult.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "refresh token has refreshable deadline",
    refreshResult.token.refreshable_until.length > 0,
  );
  // 6. Confirm token rotation - new refresh token must differ from old one
  TestValidator.notEquals(
    "refresh token rotated",
    originalRefreshToken,
    refreshResult.token.refresh,
  );
  // 7. Verify customer identity remains consistent after refresh
  TestValidator.equals("customer id matches", joinResult.id, refreshResult.id);
  TestValidator.equals(
    "customer email matches",
    joinResult.email,
    refreshResult.email,
  );
  TestValidator.equals(
    "profile id matches",
    joinResult.profile.id,
    refreshResult.profile.id,
  );
  TestValidator.equals(
    "display name matches",
    joinResult.profile.display_name,
    refreshResult.profile.display_name,
  );
  TestValidator.equals(
    "phone number matches",
    joinResult.profile.phone_number,
    refreshResult.profile.phone_number,
  );
  // 8. Validate new access token is valid JWT format (three parts separated by dots)
  TestValidator.predicate(
    "new token is valid JWT format",
    refreshResult.token.access.split(".").length === 3,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
