import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallSellerProfileSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSellerProfileSnapshot";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallCustomerProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerProfile";
import type { IShoppingMallSellerProfileSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerProfileSnapshot";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_customer_join } from "../../../authorize/authorize_customer_join";
import { authorize_customer_login } from "../../../authorize/authorize_customer_login";
import { authorize_customer_refresh } from "../../../authorize/authorize_customer_refresh";

/**
 * Test customer profile snapshot history retrieval.
 *
 * This test verifies that an authenticated customer can retrieve their profile
 * snapshot audit history. The test flow:
 * 1. Customer joins the platform
 * 2. Customer updates profile multiple times to create snapshots
 * 3. Customer retrieves snapshot history
 * 4. Validate snapshot ordering, content, and pagination metadata
 */
export async function test_api_customer_profile_snapshot_history_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Customer joins the platform
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(customerAuth);
  // Step 2: Update customer profile multiple times to create snapshot history
  const profileUpdate1 =
    await api.functional.shoppingMall.customer.profile.update(
      customerConnection,
      {
        body: {
          display_name: RandomGenerator.name(),
          phone_number: RandomGenerator.mobile(),
        } satisfies IShoppingMallCustomerProfile.IUpdate,
      },
    );
  typia.assert(profileUpdate1);
  const profileUpdate2 =
    await api.functional.shoppingMall.customer.profile.update(
      customerConnection,
      {
        body: {
          display_name: RandomGenerator.name(),
          phone_number: RandomGenerator.mobile(),
        } satisfies IShoppingMallCustomerProfile.IUpdate,
      },
    );
  typia.assert(profileUpdate2);
  const profileUpdate3 =
    await api.functional.shoppingMall.customer.profile.update(
      customerConnection,
      {
        body: {
          display_name: RandomGenerator.name(),
          phone_number: RandomGenerator.mobile(),
        } satisfies IShoppingMallCustomerProfile.IUpdate,
      },
    );
  typia.assert(profileUpdate3);
  // Step 3: Retrieve snapshot history
  const snapshotResponse =
    await api.functional.shoppingMall.customer.profile.snapshots.index(
      customerConnection,
      {
        body: {
          page: 1,
          limit: 10,
        } satisfies IShoppingMallSellerProfileSnapshot.IRequest,
      },
    );
  typia.assert(snapshotResponse);
  // Step 4: Validate pagination metadata
  TestValidator.equals("current page", snapshotResponse.pagination.current, 1);
  TestValidator.equals("limit", snapshotResponse.pagination.limit, 10);
  TestValidator.predicate(
    "records count non-negative",
    snapshotResponse.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pages count non-negative",
    snapshotResponse.pagination.pages >= 0,
  );
  // Step 5: Validate snapshot data structure and ordering
  TestValidator.predicate(
    "snapshots array exists",
    Array.isArray(snapshotResponse.data),
  );
  // Validate snapshots are in descending order by created_at (newest first)
  if (snapshotResponse.data.length > 1) {
    for (let i = 0; i < snapshotResponse.data.length - 1; i++) {
      const current = new Date(snapshotResponse.data[i].created_at).getTime();
      const next = new Date(snapshotResponse.data[i + 1].created_at).getTime();
      TestValidator.predicate(
        `snapshot ${i} is newer than or equal to snapshot ${i + 1}`,
        current >= next,
      );
    }
  }
  // Validate pagination pages calculation is correct
  const expectedPages = Math.ceil(
    snapshotResponse.pagination.records / snapshotResponse.pagination.limit,
  );
  TestValidator.equals(
    "pages calculation",
    snapshotResponse.pagination.pages,
    expectedPages,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
