/**
 * Test that sellers can filter product snapshots by creation date range using created_at_from and created_at_to parameters.
 *
 * This test validates the date range filtering functionality for product snapshot audit trails.
 * Sellers can browse historical product states by filtering snapshots within specific time periods.
 */
export async function test_api_product_snapshot_date_range_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seller authentication
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(sellerAuth);
  // 2. Create initial product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        category_id: typia.random<string & tags.Format<"uuid">>(),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 3. Create multiple snapshots by editing the product multiple times
  // First edit - creates snapshot 1
  const update1 = await api.functional.shoppingMall.seller.products.update(
    sellerConnection,
    {
      productId: product.id,
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        base_price: product.base_price + 1000,
      } satisfies IShoppingMallProduct.IUpdate,
    },
  );
  typia.assert(update1);
  // Small delay to ensure different timestamps
  await new Promise((resolve) => setTimeout(resolve, 100));
  // Second edit - creates snapshot 2
  const update2 = await api.functional.shoppingMall.seller.products.update(
    sellerConnection,
    {
      productId: product.id,
      body: {
        description: RandomGenerator.content({ paragraphs: 2 }),
        base_price: product.base_price + 2000,
      } satisfies IShoppingMallProduct.IUpdate,
    },
  );
  typia.assert(update2);
  // Small delay to ensure different timestamps
  await new Promise((resolve) => setTimeout(resolve, 100));
  // Third edit - creates snapshot 3
  const update3 = await api.functional.shoppingMall.seller.products.update(
    sellerConnection,
    {
      productId: product.id,
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
      } satisfies IShoppingMallProduct.IUpdate,
    },
  );
  typia.assert(update3);
  // 4. Get all snapshots to establish baseline
  const allSnapshots =
    await api.functional.shoppingMall.seller.products.snapshots.index(
      sellerConnection,
      {
        productId: product.id,
        body: {
          page: 1,
          limit: 100,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );
  typia.assert(allSnapshots);
  // We should have at least 3 snapshots (from 3 edits plus initial creation)
  TestValidator.predicate(
    "has multiple snapshots",
    allSnapshots.data.length >= 3,
  );
  // Sort snapshots by created_at to get boundary timestamps
  const sortedSnapshots = [...allSnapshots.data].sort(
    (a, b) =>
      new Date(a.created_at).getTime() - new Date(b.created_at).getTime(),
  );
  const firstSnapshot = sortedSnapshots[0];
  const lastSnapshot = sortedSnapshots[sortedSnapshots.length - 1];
  const middleSnapshot =
    sortedSnapshots[Math.floor(sortedSnapshots.length / 2)];
  // 5. Test created_at_from filter (snapshots on or after middle snapshot time)
  const fromFilterResult =
    await api.functional.shoppingMall.seller.products.snapshots.index(
      sellerConnection,
      {
        productId: product.id,
        body: {
          page: 1,
          limit: 100,
          created_at_from: middleSnapshot.created_at,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );
  typia.assert(fromFilterResult);
  // Validate all returned snapshots are on or after the from date
  for (const snapshot of fromFilterResult.data) {
    TestValidator.predicate(
      `snapshot ${snapshot.id} is after from date`,
      new Date(snapshot.created_at).getTime() >=
        new Date(middleSnapshot.created_at).getTime(),
    );
  }
  // 6. Test created_at_to filter (snapshots on or before middle snapshot time)
  const toFilterResult =
    await api.functional.shoppingMall.seller.products.snapshots.index(
      sellerConnection,
      {
        productId: product.id,
        body: {
          page: 1,
          limit: 100,
          created_at_to: middleSnapshot.created_at,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );
  typia.assert(toFilterResult);
  // Validate all returned snapshots are on or before the to date
  for (const snapshot of toFilterResult.data) {
    TestValidator.predicate(
      `snapshot ${snapshot.id} is before to date`,
      new Date(snapshot.created_at).getTime() <=
        new Date(middleSnapshot.created_at).getTime(),
    );
  }
  // 7. Test combined created_at_from and created_at_to filter (date range)
  // Use first and last snapshot timestamps as boundaries
  const rangeFilterResult =
    await api.functional.shoppingMall.seller.products.snapshots.index(
      sellerConnection,
      {
        productId: product.id,
        body: {
          page: 1,
          limit: 100,
          created_at_from: firstSnapshot.created_at,
          created_at_to: lastSnapshot.created_at,
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );
  typia.assert(rangeFilterResult);
  // Validate all returned snapshots are within the date range
  for (const snapshot of rangeFilterResult.data) {
    TestValidator.predicate(
      `snapshot ${snapshot.id} is within date range`,
      new Date(snapshot.created_at).getTime() >=
        new Date(firstSnapshot.created_at).getTime() &&
        new Date(snapshot.created_at).getTime() <=
          new Date(lastSnapshot.created_at).getTime(),
    );
  }
  // 8. Test edge case: date range that matches no snapshots (future date)
  const futureDate = new Date();
  futureDate.setDate(futureDate.getDate() + 365); // 1 year in the future
  const emptyResult =
    await api.functional.shoppingMall.seller.products.snapshots.index(
      sellerConnection,
      {
        productId: product.id,
        body: {
          page: 1,
          limit: 20,
          created_at_from: futureDate.toISOString(),
        } satisfies IShoppingMallProductSnapshot.IRequest,
      },
    );
  typia.assert(emptyResult);
  // Validate empty result set
  TestValidator.equals("empty data array", emptyResult.data, []);
  TestValidator.equals("zero records", emptyResult.pagination.records, 0);
  TestValidator.equals("zero pages", emptyResult.pagination.pages, 0);
  // 9. Validate pagination metadata reflects filtered counts
  TestValidator.predicate(
    "from filter pagination is correct",
    fromFilterResult.pagination.records === fromFilterResult.data.length,
  );
  TestValidator.predicate(
    "to filter pagination is correct",
    toFilterResult.pagination.records === toFilterResult.data.length,
  );
  TestValidator.predicate(
    "range filter pagination is correct",
    rangeFilterResult.pagination.records === rangeFilterResult.data.length,
  );
  // 10. Verify snapshot data integrity (snapshots are immutable)
  for (const snapshot of allSnapshots.data) {
    TestValidator.predicate("snapshot has valid id", snapshot.id.length > 0);
    TestValidator.predicate("snapshot has name", snapshot.name.length > 0);
    TestValidator.predicate("snapshot has base_price", snapshot.base_price > 0);
    TestValidator.predicate(
      "snapshot has valid created_at",
      snapshot.created_at.length > 0,
    );
    TestValidator.predicate(
      "snapshot has category reference",
      snapshot.category.id.length > 0,
    );
  }
}

