    async () => {
      await api.functional.shoppingMall.seller.products.variants.snapshots.at(
        sellerBConnection,
        {
          productId: product.id,
          variantId: variant.id,
          variantSnapshotId: variantSnapshotId,
        },
      );
    },
  );
}

