/**
 * Test cart item quantity update functionality.
 *
 * This test verifies the complete cart item quantity update workflow:
 * 1. Customer joins and authenticates
 * 2. Customer adds a product variant to their cart
 * 3. Customer updates the cart item quantity to a higher value
 * 4. Verify quantity increased, updated_at timestamp changed
 * 5. Customer updates the cart item quantity to a lower value
 * 6. Verify quantity decreased, price snapshot preserved, item remains in cart
 */
export async function test_api_cart_item_quantity_update(
  connection: api.IConnection,
): Promise<void> {
  // 1. Customer authentication
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(customerAuth);
  // 2. Add product variant to cart with initial quantity of 2
  const cartItem =
    await generate_random_shopping_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          quantity: 2,
        },
      },
    );
  typia.assert(cartItem);
  // Store initial values for comparison
  const initialQuantity = cartItem.quantity;
  const initialUpdatedAt = cartItem.updated_at;
  const priceSnapshot = cartItem.price;
  // 3. Update quantity to a higher value (5)
  const increasedQuantity = 5;
  const updatedCartItemIncrease =
    await api.functional.shoppingMall.customer.cart.items.putByCartitemid(
      customerConnection,
      {
        cartItemId: cartItem.id,
        body: {
          quantity: increasedQuantity,
        } satisfies IShoppingMallCartItem.IUpdate,
      },
    );
  typia.assert(updatedCartItemIncrease);
  // 4. Verify increased quantity
  TestValidator.equals(
    "quantity increased",
    updatedCartItemIncrease.quantity,
    increasedQuantity,
  );
  TestValidator.predicate(
    "quantity is higher",
    updatedCartItemIncrease.quantity > initialQuantity,
  );
  TestValidator.notEquals(
    "updated_at changed",
    updatedCartItemIncrease.updated_at,
    initialUpdatedAt,
  );
  TestValidator.equals(
    "price snapshot preserved",
    updatedCartItemIncrease.price,
    priceSnapshot,
  );
  // Store updated timestamp for second comparison
  const secondUpdatedAt = updatedCartItemIncrease.updated_at;
  // 5. Update quantity to a lower value (3, but still >= 1)
  const decreasedQuantity = 3;
  const updatedCartItemDecrease =
    await api.functional.shoppingMall.customer.cart.items.putByCartitemid(
      customerConnection,
      {
        cartItemId: cartItem.id,
        body: {
          quantity: decreasedQuantity,
        } satisfies IShoppingMallCartItem.IUpdate,
      },
    );
  typia.assert(updatedCartItemDecrease);
  // 6. Verify decreased quantity
  TestValidator.equals(
    "quantity decreased",
    updatedCartItemDecrease.quantity,
    decreasedQuantity,
  );
  TestValidator.predicate(
    "quantity is lower",
    updatedCartItemDecrease.quantity < updatedCartItemIncrease.quantity,
  );
  TestValidator.predicate(
    "quantity is at least 1",
    updatedCartItemDecrease.quantity >= 1,
  );
  TestValidator.notEquals(
    "updated_at changed again",
    updatedCartItemDecrease.updated_at,
    secondUpdatedAt,
  );
  TestValidator.equals(
    "price snapshot still preserved",
    updatedCartItemDecrease.price,
    priceSnapshot,
  );
  TestValidator.equals(
    "cart item id unchanged",
    updatedCartItemDecrease.id,
    cartItem.id,
  );
  TestValidator.equals(
    "product variant unchanged",
    updatedCartItemDecrease.productVariant.id,
    cartItem.productVariant.id,
  );
}

