  TestValidator.equals(
    "price snapshot matches",
    retrievedItem.price,
    cartItem.price,
  );
  TestValidator.equals(
    "cart ID matches",
    retrievedItem.cart.id,
    cartItem.cart.id,
  );
  TestValidator.equals(
    "product variant ID matches",
