/**
 * Test that a seller can successfully retrieve the immutable snapshot of an order item for their sold product.
 *
 * Test Flow:
 * 1. Register and authenticate a seller account
 * 2. Seller creates a product with variants
 * 3. Register and authenticate a customer account
 * 4. Customer places an order (system creates order with items)
 * 5. Seller retrieves the order item snapshot using the order item ID
 *
 * Validation:
 * - Snapshot contains product name and description as they existed at purchase time
 * - Snapshot contains variant SKU code and price
 * - Snapshot contains seller shop name and logo
 * - Snapshot contains variant option values
 * - Snapshot has creation timestamp
 * - Snapshot is immutable (read-only)
 */
export async function test_api_order_item_snapshot_retrieval_by_seller(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate seller
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(sellerAuth);
  // 2. Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 3 }),
        category_id: typia.random<string & tags.Format<"uuid">>(),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 3. Seller creates a product variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku_code: RandomGenerator.alphaNumeric(12),
          price_override: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1000>
          >(),
          option_value_ids: ArrayUtil.repeat(2, () =>
            typia.random<string & tags.Format<"uuid">>(),
          ),
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(variant);
  // 4. Register and authenticate customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(customerAuth);
  // 5. Customer places an order containing the seller's product variant
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        shopping_mall_address_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);
  // 6. Get the order item ID from the order
  const orderItem = order.orderItems[0];
  TestValidator.predicate("order has items", () => order.orderItems.length > 0);
  // 7. Seller retrieves the order item snapshot
  const snapshot =
    await api.functional.shoppingMall.seller.orders.items.snapshots.patchByItemid(
      sellerConnection,
      {
        itemId: orderItem.id,
      },
    );
  typia.assert(snapshot);
  // 8. Validate snapshot contains expected data
  TestValidator.equals(
    "snapshot order item ID matches",
    snapshot.orderItemId,
    orderItem.id,
  );
  TestValidator.equals(
    "snapshot product name matches",
    snapshot.productName,
    product.name,
  );
  TestValidator.equals(
    "snapshot product description matches",
    snapshot.productDescription,
    product.description,
  );
  TestValidator.equals(
    "snapshot variant SKU matches",
    snapshot.variantSkuCode,
    variant.skuCode,
  );
  TestValidator.predicate(
    "snapshot has valid price",
    () => snapshot.variantPrice > 0,
  );
  TestValidator.predicate(
    "snapshot has seller shop name",
    () => snapshot.sellerShopName.length > 0,
  );
  TestValidator.predicate(
    "snapshot has creation timestamp",
    () => snapshot.createdAt.length > 0,
  );
  TestValidator.predicate("snapshot has variant options array", () =>
    Array.isArray(snapshot.variantOptions),
  );
}

