/**
 * Test retrieving variant option values from an order item snapshot.
 *
 * This test validates that customers can retrieve the product option values
 * (Color, Size, etc.) that were captured at purchase time and preserved in
 * the order item snapshot. The snapshot data should be immutable and reflect
 * the exact variant configuration at the time of order placement.
 *
 * Test Flow:
 * 1. Seller creates product with option definitions (Color, Size)
 * 2. Seller creates option values (Red, Large) and a variant combining them
 * 3. Customer places an order for the variant
 * 4. Customer retrieves variant options from the order item snapshot
 * 5. Validate that snapshot contains correct option names and values
 */
export async function test_api_order_item_snapshot_variant_options_retrieval(
  connection: api.IConnection,
