          >(),
          option_value_ids: [redOptionValue.id, largeOptionValue.id],
        },
      },
    );
  typia.assert(variant);
  // 8. Customer setup - register and login
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "CustomerPass123!";
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(customerAuth);
  const customerLoginConnection: api.IConnection = { host: connection.host };
  await authorize_customer_login(customerLoginConnection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    },
  });
  // 9. Create shipping address
  const address = await generate_random_shopping_mall_customer_addresses_create(
    customerLoginConnection,
    {
      body: {
        recipientName: RandomGenerator.name(),
        recipientPhone: RandomGenerator.mobile(),
        streetAddress: RandomGenerator.paragraph({ sentences: 1 }),
        city: RandomGenerator.name(),
        state: RandomGenerator.name(),
        postalCode: typia.random<string>(),
        country: "South Korea",
        isDefault: true,
      },
    },
  );
  typia.assert(address);
  // 10. Add variant to cart
  const cartItem =
    await generate_random_shopping_mall_customer_cart_items_create(
      customerLoginConnection,
      {
        body: {
          shopping_mall_product_variant_id: variant.id,
          quantity: typia.random<
            number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
        },
      },
    );
  typia.assert(cartItem);
  // 11. Create order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerLoginConnection,
    {
      body: {
        shopping_mall_address_id: address.id,
      },
    },
  );
  typia.assert(order);
  // 12. Get the first order item
  const orderItem = order.orderItems[0];
  TestValidator.predicate("order has items", order.orderItems.length > 0);
  // 13. Retrieve variant options from order item snapshot
  // Note: snapshotId should be obtained from order item snapshot list in real scenario
  // For this test, we use the order item's created_at as reference
  const snapshotId = typia.random<string & tags.Format<"uuid">>();
  const variantOptions =
    await api.functional.shoppingMall.customer.orders.items.snapshots.variant_options.index(
      customerLoginConnection,
      {
        orderId: order.id,
        itemId: orderItem.id,
        snapshotId: snapshotId,
        body: {
          page: 1,
          limit: 10,
          sort: ["createdAt"],
        },
      },
    );
  typia.assert(variantOptions);
  // 14. Validate pagination metadata
  TestValidator.equals("current page", variantOptions.pagination.current, 1);
  TestValidator.predicate("limit is set", variantOptions.pagination.limit > 0);
  TestValidator.predicate(
    "records count",
    variantOptions.pagination.records >= 0,
  );
  TestValidator.predicate("pages count", variantOptions.pagination.pages >= 0);
  // 15. Validate variant options data exists
  TestValidator.predicate(
    "has variant options",
    variantOptions.data.length > 0,
  );
  // 16. Validate each variant option has required fields (typia.assert already validates structure)
  const firstOption = variantOptions.data[0];
  TestValidator.predicate("option has name", firstOption.optionName.length > 0);
  TestValidator.predicate(
    "option has value",
    firstOption.optionValue.length > 0,
  );
  // 17. Verify the options match what was configured (Color=Red, Size=Large)
  const optionNames = variantOptions.data.map((o) => o.optionName);
  const optionValues = variantOptions.data.map((o) => o.optionValue);
  TestValidator.predicate("has Color option", optionNames.includes("Color"));
  TestValidator.predicate("has Size option", optionNames.includes("Size"));
  TestValidator.predicate("has Red value", optionValues.includes("Red"));
  TestValidator.predicate("has Large value", optionValues.includes("Large"));
}

