/**
 * Test seller creating a shipment with multiple order items.
 *
 * This test validates the complete shipment creation workflow:
 * 1. Seller registers and logs in
 * 2. Customer registers, logs in, creates address, and adds items to cart
 * 3. Customer creates order generating order items with 'paid' status
 * 4. Seller creates shipment with multiple order item IDs
 * 5. Verifies shipment contains correct tracking information
 * 6. Verifies all order items transition from 'paid' to 'shipped' status
 * 7. Verifies shipment items are properly linked to order items
 */
export async function test_api_shipment_creation_multiple_items(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seller setup - register and login
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerAuth);
  // 2. Customer setup - register and login
  const customerPassword = RandomGenerator.alphaNumeric(16);
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: customerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(customerAuth);
