  TestValidator.equals(
    "actor type is seller",
    retrievedLog.actorType,
    "seller",
  );
  TestValidator.predicate(
    "actor ID exists for seller event",
    () => retrievedLog.actorId !== null,
  );
  TestValidator.equals(
    "old status is null for creation",
    retrievedLog.oldStatus,
