    () =>
      retrievedLog.createdAt !== null &&
      new Date(retrievedLog.createdAt).getTime() > 0,
  );
  TestValidator.equals(
    "shipment ID matches",
    retrievedLog.shipment.id,
    shipment.id,
  );
}

