export async function test_api_cancellation_request_seller_filter_by_status(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seller Setup - Register and login
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    },
  });
  typia.assert(sellerAuth);
  const sellerLoginConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(sellerLoginConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.ILogin,
  });
  // 2. Seller creates product with variant
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerLoginConnection,
    {},
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerLoginConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 3. Customer Setup - Register and login
  const customerPassword = RandomGenerator.alphaNumeric(16);
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    },
  });
  typia.assert(customerAuth);
  const customerLoginConnection: api.IConnection = { host: connection.host };
  await authorize_customer_login(customerLoginConnection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    } satisfies IShoppingMallCustomer.ILogin,
  });
  // 4. Customer creates order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerLoginConnection,
    {},
  );
  typia.assert(order);
  // 5. Get order items for cancellation requests
  const orderItems = order.orderItems;
  TestValidator.predicate("order has items", orderItems.length > 0);
  // 6. Create multiple cancellation requests for different order items
  const cancellationRequests: IShoppingMallCancellationRequest[] = [];
  // Create cancellation request for first order item
  const cancelRequest1 =
    await generate_random_shopping_mall_customer_order_items_cancellation_requests_create(
      customerLoginConnection,
      {
        params: { orderItemId: orderItems[0].id },
        body: {
          reason: "Changed my mind about this item",
        },
      },
    );
  typia.assert(cancelRequest1);
  cancellationRequests.push(cancelRequest1);
  // Create cancellation request for second order item if exists
  let cancelRequest2: IShoppingMallCancellationRequest | undefined;
  if (orderItems.length > 1) {
    cancelRequest2 =
      await generate_random_shopping_mall_customer_order_items_cancellation_requests_create(
        customerLoginConnection,
        {
          params: { orderItemId: orderItems[1].id },
          body: {
            reason: "Found better price elsewhere",
          },
        },
      );
    typia.assert(cancelRequest2);
    cancellationRequests.push(cancelRequest2);
  }
  // 7. Seller responds to cancellation requests - approve first, reject second
  const approvedRequest =
    await api.functional.shoppingMall.seller.order_items.cancellation_requests.update(
      sellerLoginConnection,
      {
        orderItemId: orderItems[0].id,
        cancellationRequestId: cancelRequest1.id,
        body: {
          status: "approved",
          responseReason: "Approved - customer request honored",
        } satisfies IShoppingMallCancellationRequest.IUpdate,
      },
    );
  typia.assert(approvedRequest);
  TestValidator.equals(
    "first request approved",
    approvedRequest.status,
    "approved",
  );
  let rejectedRequest: IShoppingMallCancellationRequest | undefined;
  if (cancelRequest2) {
    rejectedRequest =
      await api.functional.shoppingMall.seller.order_items.cancellation_requests.update(
        sellerLoginConnection,
        {
          orderItemId: orderItems[1].id,
          cancellationRequestId: cancelRequest2.id,
          body: {
            status: "rejected",
            responseReason: "Rejected - item already prepared for shipment",
          } satisfies IShoppingMallCancellationRequest.IUpdate,
        },
      );
    typia.assert(rejectedRequest);
    TestValidator.equals(
      "second request rejected",
      rejectedRequest.status,
      "rejected",
    );
  }
  // 8. Test filtering by status - PENDING
  const pendingResult =
    await api.functional.shoppingMall.seller.order_items.cancellation_requests.index(
      sellerLoginConnection,
      {
        orderItemId: orderItems[0].id,
        body: {
          status: "pending",
          page: 1,
          limit: 10,
        } satisfies IShoppingMallCancellationRequest.IRequest,
      },
    );
  typia.assert(pendingResult);
  // 9. Test filtering by status - APPROVED
  const approvedResult =
    await api.functional.shoppingMall.seller.order_items.cancellation_requests.index(
      sellerLoginConnection,
      {
        orderItemId: orderItems[0].id,
        body: {
          status: "approved",
          page: 1,
          limit: 10,
        } satisfies IShoppingMallCancellationRequest.IRequest,
      },
    );
  typia.assert(approvedResult);
  // Should have at least one approved request
  TestValidator.predicate(
    "approved filter - has results",
    approvedResult.data.length >= 1,
  );
  // Verify our approved request is in the results
  const foundApproved = approvedResult.data.some(
    (r) => r.id === approvedRequest.id,
  );
  TestValidator.predicate(
    "approved filter - contains our approved request",
    foundApproved,
  );
  // 10. Test filtering by status - REJECTED
  if (rejectedRequest) {
    const rejectedResult =
      await api.functional.shoppingMall.seller.order_items.cancellation_requests.index(
        sellerLoginConnection,
        {
          orderItemId: orderItems[1].id,
          body: {
            status: "rejected",
            page: 1,
            limit: 10,
          } satisfies IShoppingMallCancellationRequest.IRequest,
        },
      );
    typia.assert(rejectedResult);
    // Should have at least one rejected request
    TestValidator.predicate(
      "rejected filter - has results",
      rejectedResult.data.length >= 1,
    );
    // Verify our rejected request is in the results
    const foundRejected = rejectedResult.data.some(
      (r) => r.id === rejectedRequest.id,
    );
    TestValidator.predicate(
      "rejected filter - contains our rejected request",
      foundRejected,
    );
  }
}

