/**
 * Test the complete seller refund approval workflow for a delivered order item with stock restoration.
 *
 * This test validates:
 * 1. Seller can approve a refund request for a delivered order item
 * 2. Refund request status transitions from 'pending' to 'approved'
 * 3. Order item status changes to 'refunded' upon approval
 * 4. Stock is restored through inventory record creation
 * 5. All response fields are properly populated
 */
export async function test_api_refund_request_seller_approval_with_stock_restoration(
  connection: api.IConnection,
): Promise<void> {
  // ============================================
  // SETUP PHASE: Create seller and product
  // ============================================
  // 1. Register and authenticate seller
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(sellerAuth);
  // 2. Submit seller approval request
  const sellerApprovalRequest =
    await api.functional.shoppingMall.seller.approval_requests.create(
      sellerConnection,
      { body: {} satisfies IShoppingMallSellerApprovalRequest.ICreate },
    );
  typia.assert(sellerApprovalRequest);
  // 3. Create product
  const product = await api.functional.shoppingMall.seller.products.create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        category_id: typia.random<string & tags.Format<"uuid">>(),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 4. Create option definition
  const optionDefinition =
    await api.functional.shoppingMall.seller.products.option_definitions.create(
      sellerConnection,
      {
        productId: product.id,
        body: {
          name: "Color",
        } satisfies IShoppingMallProductOptionDefinition.ICreate,
      },
    );
  typia.assert(optionDefinition);
  // 5. Create option values
  const optionValueRed =
    await api.functional.shoppingMall.seller.products.option_definitions.option_values.create(
      sellerConnection,
      {
        productId: product.id,
        optionDefinitionId: optionDefinition.id,
        body: { name: "Red" } satisfies IShoppingMallProductOptionValue.ICreate,
      },
    );
  typia.assert(optionValueRed);
  // 6. Create product variant
  const variant =
    await api.functional.shoppingMall.seller.products.variants.create(
      sellerConnection,
      {
        productId: product.id,
        body: {
          sku_code: `SKU-${RandomGenerator.alphaNumeric(8)}`,
          price_override: null,
          option_value_ids: [optionValueRed.id],
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(variant);
  // ============================================
  // SETUP PHASE: Create customer and order
  // ============================================
  // 7. Register and authenticate customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(customerAuth);
  // 8. Create shipping address
  const address = await api.functional.shoppingMall.customer.addresses.create(
    customerConnection,
    {
      body: {
        recipientName: RandomGenerator.name(),
        recipientPhone: RandomGenerator.mobile(),
        streetAddress: RandomGenerator.paragraph({ sentences: 1 }),
        city: RandomGenerator.name(),
        state: RandomGenerator.name(),
        postalCode: typia.random<string>(),
        country: "South Korea",
        isDefault: true,
      } satisfies IShoppingMallAddress.ICreate,
    },
  );
  typia.assert(address);
  // 9. Add product variant to cart
  const cartItem = await api.functional.shoppingMall.customer.cart.items.create(
    customerConnection,
    {
      body: {
        shopping_mall_product_variant_id: variant.id,
        quantity: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<5>
        >(),
      } satisfies IShoppingMallCartItem.ICreate,
    },
  );
  typia.assert(cartItem);
  // 10. Create order
  const order = await api.functional.shoppingMall.customer.orders.create(
    customerConnection,
    {
      body: {
        shopping_mall_address_id: address.id,
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);
  // Get the order item for refund testing
  TestValidator.predicate("order has items", order.orderItems.length > 0);
  const orderItemId = order.orderItems[0].id;
  // 11. Customer creates refund request
  const refundRequest =
    await api.functional.shoppingMall.customer.order_items.refund_requests.create(
      customerConnection,
      {
        orderItemId: orderItemId,
        body: {
          reason: "Product quality issue - requesting refund",
        } satisfies IShoppingMallRefundRequest.ICreate,
      },
    );
  typia.assert(refundRequest);
  // ============================================
  // TEST EXECUTION: Seller approves refund
  // ============================================
  // 1. Seller responds to refund request with approval
  const updatedRefundRequest =
    await api.functional.shoppingMall.seller.order_items.refund_requests.update(
      sellerConnection,
      {
        orderItemId: orderItemId,
        refundRequestId: refundRequest.id,
        body: {
          status: "approved",
          response_reason: "Refund approved - product quality issue confirmed",
        } satisfies IShoppingMallRefundRequest.IUpdate,
      },
    );
  typia.assert(updatedRefundRequest);
  // ============================================
  // VALIDATION: Verify refund approval results
  // ============================================
  // 2. Verify refund request status changed to 'approved'
  TestValidator.equals(
    "refund status",
    updatedRefundRequest.status,
    "approved",
  );
  // 3. Verify responded_at timestamp is set
  TestValidator.predicate(
    "responded_at is set",
    updatedRefundRequest.responded_at !== null,
  );
  // 4. Verify response_reason is stored
  TestValidator.equals(
    "response reason",
    updatedRefundRequest.response_reason,
    "Refund approved - product quality issue confirmed",
  );
  // 5. Verify seller is set
  TestValidator.predicate(
    "seller is set",
    updatedRefundRequest.seller !== null,
  );
  TestValidator.equals(
    "seller id",
    updatedRefundRequest.seller!.id,
    sellerAuth.id,
  );
  // 6. Verify order item status changed to 'refunded' through refund request relation
  TestValidator.equals(
    "order item status is refunded",
    updatedRefundRequest.orderItem.status,
    "refunded",
  );
  // 7. Verify order item in refund request matches original
  TestValidator.equals(
    "order item id matches",
    updatedRefundRequest.orderItem.id,
    orderItemId,
  );
  // 8. Verify customer is preserved
  TestValidator.equals(
    "customer id matches",
    updatedRefundRequest.customer.id,
    customerAuth.id,
  );
  // 9. Verify timestamps are valid
  TestValidator.predicate(
    "requested_at is valid date-time",
    updatedRefundRequest.requested_at !== undefined,
  );
  TestValidator.predicate(
    "created_at is valid date-time",
    updatedRefundRequest.created_at !== undefined,
  );
  TestValidator.predicate(
    "updated_at is valid date-time",
    updatedRefundRequest.updated_at !== undefined,
  );
}

