/**
 * Test the seller refund rejection workflow where the seller denies the customer's refund request.
 *
 * This test verifies that when a seller rejects a refund request:
 * 1. The refund request status changes from 'pending' to 'rejected'
 * 2. The responded_at timestamp is set
 * 3. The response_reason contains the rejection explanation
 * 4. The order item status remains 'delivered' (not changed to refunded)
 * 5. No inventory restoration occurs (stock not restored on rejection)
 */
export async function test_api_refund_request_seller_rejection_keeps_item_delivered(
  connection: api.IConnection,
): Promise<void> {
  // =========================================================================
  // SETUP PHASE: Seller Registration and Product Creation
  // =========================================================================
  // 1. Register and authenticate seller account
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "SellerPass123!",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerAuth);
  // 2. Submit seller approval request
  const sellerApprovalRequest =
    await api.functional.shoppingMall.seller.approval_requests.create(
      sellerConnection,
      { body: {} satisfies IShoppingMallSellerApprovalRequest.ICreate },
    );
  typia.assert(sellerApprovalRequest);
  // Note: In production, admin approval would be required. For this test,
  // we proceed assuming the seller account is active and can create products.
  // 3. Create a product with required fields
  const product = await api.functional.shoppingMall.seller.products.create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        category_id: typia.random<string & tags.Format<"uuid">>(),
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 4. Create option definition for the product
  const optionDefinition =
    await api.functional.shoppingMall.seller.products.option_definitions.create(
      sellerConnection,
      {
        productId: product.id,
        body: {
          name: "Color",
        } satisfies IShoppingMallProductOptionDefinition.ICreate,
      },
    );
  typia.assert(optionDefinition);
  // 5. Create option values for the option definition
  const optionValue =
    await api.functional.shoppingMall.seller.products.option_definitions.option_values.create(
      sellerConnection,
      {
        productId: product.id,
        optionDefinitionId: optionDefinition.id,
        body: {
          name: "Red",
        } satisfies IShoppingMallProductOptionValue.ICreate,
      },
    );
  typia.assert(optionValue);
  // 6. Create a product variant with SKU and options
  const variant =
    await api.functional.shoppingMall.seller.products.variants.create(
      sellerConnection,
      {
        productId: product.id,
        body: {
          sku_code: `SKU-${RandomGenerator.alphaNumeric(8)}`,
          price_override: null,
          option_value_ids: [optionValue.id],
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(variant);
  // =========================================================================
  // SETUP PHASE: Customer Registration and Order Creation
  // =========================================================================
  // 7. Register and authenticate customer account
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "CustomerPass123!",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(customerAuth);
  // 8. Create a shipping address for the customer
  const address = await api.functional.shoppingMall.customer.addresses.create(
    customerConnection,
    {
      body: {
        recipientName: RandomGenerator.name(),
        recipientPhone: RandomGenerator.mobile(),
        streetAddress: RandomGenerator.paragraph({ sentences: 1 }),
        city: RandomGenerator.name(),
        state: RandomGenerator.name(),
        postalCode: typia.random<string>(),
        country: "South Korea",
        isDefault: true,
      } satisfies IShoppingMallAddress.ICreate,
    },
  );
  typia.assert(address);
  // 9. Add the variant to customer's cart
  const cartItem = await api.functional.shoppingMall.customer.cart.items.create(
    customerConnection,
    {
      body: {
        shopping_mall_product_variant_id: variant.id,
        quantity: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<5>
        >(),
      } satisfies IShoppingMallCartItem.ICreate,
    },
  );
  typia.assert(cartItem);
  // 10. Create an order from cart items
  const order = await api.functional.shoppingMall.customer.orders.create(
    customerConnection,
    {
      body: {
        shopping_mall_address_id: address.id,
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);
  // Get the first order item for testing
  const orderItem = order.orderItems[0];
  TestValidator.predicate("order has items", () => order.orderItems.length > 0);
  // 11. Seller updates order item status to delivered (simulate fulfillment)
  // Status progression: paid -> shipped -> delivered
  const updatedOrderItemToShipped =
    await api.functional.shoppingMall.seller.orders.items.update(
      sellerConnection,
      {
        itemId: orderItem.id,
        body: {
          status: "shipped",
        } satisfies IShoppingMallOrderItem.IUpdate,
      },
    );
  typia.assert(updatedOrderItemToShipped);
  TestValidator.equals(
    "status is shipped",
    updatedOrderItemToShipped.status,
    "shipped",
  );
  const updatedOrderItemToDelivered =
    await api.functional.shoppingMall.seller.orders.items.update(
      sellerConnection,
      {
        itemId: orderItem.id,
        body: {
          status: "delivered",
        } satisfies IShoppingMallOrderItem.IUpdate,
      },
    );
  typia.assert(updatedOrderItemToDelivered);
  TestValidator.equals(
    "status is delivered",
    updatedOrderItemToDelivered.status,
    "delivered",
  );
  // 12. Customer creates a refund request for the delivered order item
  const refundRequest =
    await api.functional.shoppingMall.customer.order_items.refund_requests.create(
      customerConnection,
      {
        orderItemId: orderItem.id,
        body: {
          reason: "Product arrived damaged and not as described",
        } satisfies IShoppingMallRefundRequest.ICreate,
      },
    );
  typia.assert(refundRequest);
  TestValidator.equals(
    "refund status is pending",
    refundRequest.status,
    "pending",
  );
  TestValidator.predicate(
    "responded_at is null for pending request",
    () => refundRequest.responded_at === null,
  );
  TestValidator.predicate(
    "response_reason is null for pending request",
    () => refundRequest.response_reason === null,
  );
  // =========================================================================
  // TEST EXECUTION: Seller Rejects Refund Request
  // =========================================================================
  // 1. Seller responds to the refund request with status='rejected' and rejection reason
  const rejectionReason =
    "Customer did not provide sufficient evidence of damage. Photos required.";
  const updatedRefundRequest =
    await api.functional.shoppingMall.seller.order_items.refund_requests.update(
      sellerConnection,
      {
        orderItemId: orderItem.id,
        refundRequestId: refundRequest.id,
        body: {
          status: "rejected",
          response_reason: rejectionReason,
        } satisfies IShoppingMallRefundRequest.IUpdate,
      },
    );
  typia.assert(updatedRefundRequest);
  // =========================================================================
  // VALIDATION: Verify Rejection Effects
  // =========================================================================
  // 2. Verify the refund request status changes from 'pending' to 'rejected'
  TestValidator.equals(
    "refund status is rejected",
    updatedRefundRequest.status,
    "rejected",
  );
  // 3. Verify responded_at timestamp is set
  TestValidator.predicate(
    "responded_at is set",
    () => updatedRefundRequest.responded_at !== null,
  );
  TestValidator.predicate("responded_at is valid date-time", () => {
    if (updatedRefundRequest.responded_at === null) return false;
    return new Date(updatedRefundRequest.responded_at).getTime() > 0;
  });
  // 4. Verify response_reason contains the rejection explanation
  TestValidator.equals(
    "response_reason matches rejection reason",
    updatedRefundRequest.response_reason,
    rejectionReason,
  );
  // 5. Verify the order item status remains 'delivered' (not changed to refunded)
  // The orderItem in the refund request response reflects the current state
  TestValidator.equals(
    "order item status remains delivered",
    updatedRefundRequest.orderItem.status,
    "delivered",
  );
  // 6. Verify the seller is now assigned to the refund request
  TestValidator.predicate(
    "seller is assigned to refund request",
    () => updatedRefundRequest.seller !== null,
  );
  TestValidator.equals(
    "seller id matches",
    updatedRefundRequest.seller!.id,
    sellerAuth.id,
  );
  // 7. Verify the customer information is preserved
  TestValidator.equals(
    "customer id matches",
    updatedRefundRequest.customer.id,
    customerAuth.id,
  );
  // 8. Verify all timestamps are properly set
  TestValidator.predicate(
    "requested_at is set",
    () => updatedRefundRequest.requested_at !== null,
  );
  TestValidator.predicate(
    "created_at is set",
    () => updatedRefundRequest.created_at !== null,
  );
  TestValidator.predicate(
    "updated_at is set after rejection",
    () => updatedRefundRequest.updated_at !== null,
  );
  // 9. Verify the order item details in the refund request match the original
  TestValidator.equals(
    "order item id matches",
    updatedRefundRequest.orderItem.id,
    orderItem.id,
  );
  TestValidator.equals(
    "order item quantity matches",
    updatedRefundRequest.orderItem.quantity,
    orderItem.quantity,
  );
  TestValidator.equals(
    "order item price matches",
    updatedRefundRequest.orderItem.price,
    orderItem.price,
  );
  // 10. Verify product and variant information is preserved in order item
  // Note: product is ISummary type - skip id check, verify variant instead
  TestValidator.equals(
    "variant id matches",
    updatedRefundRequest.orderItem.productVariant.id,
    variant.id,
  );
  // 11. Verify refund request ID is preserved
  TestValidator.equals(
    "refund request id unchanged",
    updatedRefundRequest.id,
    refundRequest.id,
  );
  // 12. Verify reason from customer is preserved
  TestValidator.equals(
    "customer reason preserved",
    updatedRefundRequest.reason,
    "Product arrived damaged and not as described",
  );
}

