export async function test_api_refund_request_snapshot_after_seller_approval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Customer registration and authentication
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(customer);
  // 2. Customer creates shipping address
  const address = await generate_random_shopping_mall_customer_addresses_create(
    customerConnection,
    {},
  );
  typia.assert(address);
  // 3. Customer adds product variant to cart
  const cartItem =
    await generate_random_shopping_mall_customer_cart_items_create(
      customerConnection,
      {},
    );
  typia.assert(cartItem);
  // 4. Customer places order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        shopping_mall_address_id: address.id,
      },
    },
  );
  typia.assert(order);
  // Get the first order item for refund request
  TestValidator.predicate("order has items", () => order.orderItems.length > 0);
  const orderItem = order.orderItems[0];
  // 5. Seller registration and authentication
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(seller);
  // 6. Seller creates shipment for the order item
  const shipment = await generate_random_shopping_mall_seller_shipments_create(
    sellerConnection,
    {
      body: {
        order_item_ids: [orderItem.id],
        tracking_carrier: RandomGenerator.alphabets(10),
        tracking_number: RandomGenerator.alphaNumeric(20),
      },
    },
  );
  typia.assert(shipment);
  // 7. Customer confirms delivery
  const confirmedShipment =
    await api.functional.shoppingMall.customer.shipments.confirm_delivery.confirmDelivery(
      customerConnection,
      {
        shipmentId: shipment.id,
      },
    );
  typia.assert(confirmedShipment);
  TestValidator.predicate(
    "shipment confirmed",
    () => confirmedShipment.confirmed_at !== null,
  );
  // 8. Customer creates refund request
  const refundRequest =
    await generate_random_shopping_mall_customer_order_items_refund_requests_create(
      customerConnection,
      {
        params: {
          orderItemId: orderItem.id,
        },
        body: {
          reason: RandomGenerator.paragraph({ sentences: 3 }),
        },
      },
    );
  typia.assert(refundRequest);
  TestValidator.equals(
    "refund request status",
    refundRequest.status,
    "pending",
  );
  // 9. Customer retrieves refund request snapshots
  const snapshots =
    await api.functional.shoppingMall.customer.order_items.refund_requests.snapshots.index(
      customerConnection,
      {
        orderItemId: orderItem.id,
        refundRequestId: refundRequest.id,
        body: {
          page: 1,
          limit: 10,
          sort: "DESC",
        },
      },
    );
  typia.assert(snapshots);
  // Validate pagination metadata
  TestValidator.equals("current page", snapshots.pagination.current, 1);
  TestValidator.predicate(
    "limit is positive",
    () => snapshots.pagination.limit > 0,
  );
  TestValidator.predicate(
    "records count is non-negative",
    () => snapshots.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pages count is non-negative",
    () => snapshots.pagination.pages >= 0,
  );
  // Validate snapshot data structure
  TestValidator.predicate("data is array", () => Array.isArray(snapshots.data));
  // If snapshots exist, validate their structure
  if (snapshots.data.length > 0) {
    const snapshot = snapshots.data[0];
    TestValidator.predicate("snapshot has id", () => snapshot.id !== undefined);
    TestValidator.predicate(
      "snapshot has reason",
      () => snapshot.reason !== undefined,
    );
    TestValidator.predicate(
      "snapshot has status",
      () => snapshot.status !== undefined,
    );
    TestValidator.predicate(
      "snapshot has created_at",
      () => snapshot.created_at !== undefined,
    );
  }
}

