/**
 * Test the edge case where a customer retrieves refund request snapshots before the seller has responded to the refund request.
 *
 * Test Flow:
 * 1. Customer registers and authenticates
 * 2. Customer creates a shipping address
 * 3. Customer adds a product variant to cart (using utility function that handles variant ID generation)
 * 4. Customer places an order
 * 5. Customer creates a refund request for the order item with a reason
 * 6. Customer immediately retrieves the refund request snapshots (before seller responds)
 *
 * Validation Points:
 * - Verify the snapshot list is empty (data array has length 0)
 * - Verify pagination metadata shows records = 0 and pages = 0
 * - Verify no snapshots exist because seller has not yet responded
 * - Verify the refund request itself exists and has status 'pending'
 * - Verify responded_at on the refund request is null
 * - Verify response_reason on the refund request is null
 *
 * This validates that snapshots are only created when sellers respond to refund requests, not when customers create them.
 */
export async function test_api_refund_request_snapshot_empty_before_seller_response(
  connection: api.IConnection,
): Promise<void> {
  // 1. Customer registration and authentication
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123!",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(customerAuth);
  // 2. Create shipping address for order placement
  const address = await generate_random_shopping_mall_customer_addresses_create(
    customerConnection,
    {
      body: {
        recipientName: RandomGenerator.name(),
        recipientPhone: RandomGenerator.mobile(),
        streetAddress: RandomGenerator.paragraph({ sentences: 1 }),
        city: RandomGenerator.name(),
        state: RandomGenerator.name(),
        postalCode: typia.random<string>(),
        country: "South Korea",
        isDefault: true,
      } satisfies IShoppingMallAddress.ICreate,
    },
  );
  typia.assert(address);
  // 3. Add product variant to cart (prerequisite for order)
  // The utility function handles generating a valid product variant ID
  const cartItem =
    await generate_random_shopping_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          shopping_mall_product_variant_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
        } satisfies IShoppingMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);
  // 4. Create order to generate order items
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        shopping_mall_address_id: address.id,
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);
  // Get the first order item for refund request
  const orderItem = order.orderItems[0];
  TestValidator.predicate("order has items", order.orderItems.length > 0);
  // 5. Create refund request for the order item
  const refundRequest =
    await generate_random_shopping_mall_customer_order_items_refund_requests_create(
      customerConnection,
      {
        params: {
          orderItemId: orderItem.id,
        },
        body: {
          reason: RandomGenerator.paragraph({ sentences: 2 }),
        } satisfies IShoppingMallRefundRequest.ICreate,
      },
    );
  typia.assert(refundRequest);
  // Validate refund request initial state
  TestValidator.equals(
    "refund request status is pending",
    refundRequest.status,
    "pending",
  );
  TestValidator.predicate(
    "responded_at is null before seller response",
    refundRequest.responded_at === null,
  );
  TestValidator.predicate(
    "response_reason is null before seller response",
    refundRequest.response_reason === null,
  );
  // 6. Retrieve refund request snapshots (should be empty before seller responds)
  const snapshots =
    await api.functional.shoppingMall.customer.order_items.refund_requests.snapshots.index(
      customerConnection,
      {
        orderItemId: orderItem.id,
        refundRequestId: refundRequest.id,
        body: {
          page: 1,
          limit: 20,
          sort: "DESC",
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(snapshots);
  // Validate empty snapshot list
  TestValidator.equals(
    "snapshot data array is empty",
    snapshots.data.length,
    0,
  );
  TestValidator.equals(
    "pagination records is 0",
    snapshots.pagination.records,
    0,
  );
  TestValidator.equals("pagination pages is 0", snapshots.pagination.pages, 0);
  TestValidator.predicate(
    "current page is 1",
    snapshots.pagination.current >= 1,
  );
  TestValidator.predicate("limit is positive", snapshots.pagination.limit > 0);
}

