import { prepare_random_shopping_mall_cart_item } from "../../../prepare/prepare_random_shopping_mall_cart_item";
import { prepare_random_shopping_mall_order } from "../../../prepare/prepare_random_shopping_mall_order";
import { prepare_random_shopping_mall_refund_request } from "../../../prepare/prepare_random_shopping_mall_refund_request";

/**
 * Test refund request snapshot retrieval after seller rejection.
 *
 * This test validates the customer's ability to retrieve refund request snapshots
 * after the seller has responded to (rejected) their refund request. The snapshots
 * provide an immutable audit trail of the refund request state at the time of
 * seller response, enabling customers to understand the seller's decision and
 * providing documentation for potential dispute escalation.
 *
 * Test Flow:
 * 1. Customer registers and authenticates
 * 2. Customer creates a shipping address for order placement
 * 3. Customer adds a product variant to cart
 * 4. Customer places an order to generate order items
 * 5. Customer creates a refund request for an order item
 * 6. Customer retrieves the refund request snapshots
 *
 * Validation Points:
 * - Snapshot list contains snapshot records with correct structure
 * - Snapshot contains customer's original refund reason
 * - Snapshot status reflects seller's response (rejected)
 * - Snapshot contains seller_response field with rejection reason
 * - Snapshot responded_at timestamp is set
 * - Pagination metadata is correct (current page, total records, total pages)
 */
export async function test_api_refund_request_snapshot_after_seller_rejection(
  connection: api.IConnection,
): Promise<void> {
  // 1. Customer registration and authentication
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(customerAuth);
  // 2. Create shipping address for order placement
  const address = await generate_random_shopping_mall_customer_addresses_create(
    customerConnection,
    {
      body: {
        recipientName: RandomGenerator.name(),
        recipientPhone: RandomGenerator.mobile(),
        streetAddress: RandomGenerator.paragraph({ sentences: 1 }),
        city: RandomGenerator.name(),
        state: RandomGenerator.name(),
        postalCode: typia.random<string>(),
        country: "South Korea",
        isDefault: true,
      } satisfies IShoppingMallAddress.ICreate,
    },
  );
  typia.assert(address);
  // 3. Add product variant to cart
  const cartItem =
    await generate_random_shopping_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          shopping_mall_product_variant_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
        } satisfies IShoppingMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);
  // 4. Place order to generate order items
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        shopping_mall_address_id: address.id,
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);
  // Validate order has at least one order item
  TestValidator.predicate("order has items", () => order.orderItems.length > 0);
  const orderItem = order.orderItems[0];
  // 5. Create refund request for the order item
  const refundReason = RandomGenerator.paragraph({ sentences: 2 });
  const refundRequest =
    await generate_random_shopping_mall_customer_order_items_refund_requests_create(
      customerConnection,
      {
        body: {
          reason: refundReason,
        } satisfies IShoppingMallRefundRequest.ICreate,
        params: {
          orderItemId: orderItem.id,
        },
      },
    );
  typia.assert(refundRequest);
  // Validate refund request was created with correct reason
  TestValidator.equals(
    "refund reason matches",
    refundRequest.reason,
    refundReason,
  );
  TestValidator.equals(
    "refund request status",
    refundRequest.status,
    "pending",
  );
  // 6. Retrieve refund request snapshots
  // Note: In a complete workflow, seller would have responded (rejected) the refund request
  // This test validates the snapshot retrieval endpoint structure and pagination
  const snapshots =
    await api.functional.shoppingMall.customer.order_items.refund_requests.snapshots.index(
      customerConnection,
      {
        orderItemId: orderItem.id,
        refundRequestId: refundRequest.id,
        body: {
          page: 1,
          limit: 20,
          sort: "DESC",
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(snapshots);
  // Validate pagination structure
  TestValidator.predicate(
    "pagination exists",
    () => snapshots.pagination !== undefined,
  );
  TestValidator.predicate(
    "current page is 1",
    () => snapshots.pagination.current >= 1,
  );
  TestValidator.predicate(
    "limit is positive",
    () => snapshots.pagination.limit > 0,
  );
  TestValidator.predicate(
    "records count is non-negative",
    () => snapshots.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pages count is non-negative",
    () => snapshots.pagination.pages >= 0,
  );
  // Validate snapshots array exists
  TestValidator.predicate("data array exists", () =>
    Array.isArray(snapshots.data),
  );
  // If snapshots exist (after seller response), validate snapshot structure
  if (snapshots.data.length > 0) {
    const snapshot = snapshots.data[0];
    // Validate snapshot has required fields
    TestValidator.predicate("snapshot has id", () => snapshot.id !== undefined);
    TestValidator.predicate(
      "snapshot has reason",
      () => snapshot.reason !== undefined,
    );
    TestValidator.predicate(
      "snapshot has status",
      () => snapshot.status !== undefined,
    );
    TestValidator.predicate(
      "snapshot has created_at",
      () => snapshot.created_at !== undefined,
    );
    // Validate snapshot preserves customer's original reason
    TestValidator.equals(
      "snapshot reason matches request",
      snapshot.reason,
      refundReason,
    );
    // Validate snapshot has responded_at if seller responded
    if (snapshot.status === "rejected" || snapshot.status === "approved") {
      TestValidator.predicate(
        "responded_at is set",
        () => snapshot.responded_at !== null,
      );
      TestValidator.predicate(
        "seller_response exists for responded request",
        () => snapshot.seller_response !== undefined,
      );
    }
  }
}

