/**
 * Test that a seller can retrieve refund request snapshots after approving a customer's refund request.
 *
 * Prerequisites:
 * 1. Seller account created and authenticated
 * 2. Customer account created and authenticated
 * 3. Customer creates a shipping address
 * 4. Customer places an order (creating order items)
 * 5. Customer creates a refund request for the order item
 * 6. Seller responds to the refund request with approval status
 *
 * Test Steps:
 * 1. Seller calls the snapshot endpoint with the order item ID and refund request ID
 * 2. Verify the response contains a paginated list with snapshot data
 * 3. Verify the snapshot structure contains required fields
 * 4. Verify pagination metadata is correct
 * 5. Verify snapshot immutability by retrieving again
 */
export async function test_api_refund_request_snapshot_after_seller_approval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Setup seller account
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(sellerAuth);
  // 2. Setup customer account
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallCustomer.IJoin,
  });
  typia.assert(customerAuth);
  // 3. Customer creates shipping address
  const address =
    await generate_random_shopping_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 4. Customer places order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        shopping_mall_address_id: address.id,
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);
  // 5. Get first order item for refund request
  const orderItem = order.orderItems[0];
  TestValidator.predicate("order has items", order.orderItems.length > 0);
  // 6. Customer creates refund request for the order item
  const refundRequest =
    await generate_random_shopping_mall_customer_order_items_refund_requests_create(
      customerConnection,
      {
        params: {
          orderItemId: orderItem.id,
        },
        body: {
          reason: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IShoppingMallRefundRequest.ICreate,
      },
    );
  typia.assert(refundRequest);
  // 7. Seller retrieves refund request snapshots
  // Note: In a real scenario, seller would have approved the refund first
  // For this test, we verify the snapshot endpoint structure and pagination
  const snapshotResponse =
    await api.functional.shoppingMall.seller.order_items.refund_requests.snapshots.index(
      sellerConnection,
      {
        orderItemId: orderItem.id,
        refundRequestId: refundRequest.id,
        body: {
          page: 1,
          limit: 20,
          sort: "DESC",
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(snapshotResponse);
  // 8. Validate pagination metadata
  TestValidator.predicate(
    "current page is at least 1",
    snapshotResponse.pagination.current >= 1,
  );
  TestValidator.predicate(
    "limit is positive",
    snapshotResponse.pagination.limit > 0,
  );
  TestValidator.predicate(
    "records count is non-negative",
    snapshotResponse.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pages count is non-negative",
    snapshotResponse.pagination.pages >= 0,
  );
  // 9. Validate snapshot data structure if snapshots exist
  if (snapshotResponse.data.length > 0) {
    const snapshot = snapshotResponse.data[0];
    // Validate snapshot has required string fields with content
    TestValidator.predicate("snapshot has reason", snapshot.reason.length > 0);
    TestValidator.predicate(
      "snapshot has created_at timestamp",
      snapshot.created_at.length > 0,
    );
    // Validate nullable fields when present
    if (snapshot.responded_at !== null) {
      TestValidator.predicate(
        "responded_at is populated",
        snapshot.responded_at.length > 0,
      );
    }
    if (snapshot.seller_response !== null) {
      TestValidator.predicate(
        "seller_response is populated",
        snapshot.seller_response.length > 0,
      );
    }
  }
  // 10. Verify snapshot immutability by retrieving again
  const snapshotResponse2 =
    await api.functional.shoppingMall.seller.order_items.refund_requests.snapshots.index(
      sellerConnection,
      {
        orderItemId: orderItem.id,
        refundRequestId: refundRequest.id,
        body: {
          page: 1,
          limit: 20,
          sort: "DESC",
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(snapshotResponse2);
  // 11. Verify pagination is consistent
  TestValidator.equals(
    "pagination current page consistent",
    snapshotResponse.pagination.current,
    snapshotResponse2.pagination.current,
  );
  TestValidator.equals(
    "pagination limit consistent",
    snapshotResponse.pagination.limit,
    snapshotResponse2.pagination.limit,
  );
  TestValidator.equals(
    "pagination records consistent",
    snapshotResponse.pagination.records,
    snapshotResponse2.pagination.records,
  );
  TestValidator.equals(
    "pagination pages consistent",
    snapshotResponse.pagination.pages,
    snapshotResponse2.pagination.pages,
  );
  // 12. Verify snapshot data is immutable when snapshots exist
  if (snapshotResponse.data.length > 0 && snapshotResponse2.data.length > 0) {
    TestValidator.equals(
      "snapshot id immutable",
      snapshotResponse.data[0].id,
      snapshotResponse2.data[0].id,
    );
    TestValidator.equals(
      "snapshot reason immutable",
      snapshotResponse.data[0].reason,
      snapshotResponse2.data[0].reason,
    );
    TestValidator.equals(
      "snapshot status immutable",
      snapshotResponse.data[0].status,
      snapshotResponse2.data[0].status,
    );
    TestValidator.equals(
      "snapshot created_at immutable",
      snapshotResponse.data[0].created_at,
      snapshotResponse2.data[0].created_at,
    );
    // Verify nullable fields are also immutable
    TestValidator.equals(
      "snapshot seller_response immutable",
      snapshotResponse.data[0].seller_response,
      snapshotResponse2.data[0].seller_response,
    );
    TestValidator.equals(
      "snapshot responded_at immutable",
      snapshotResponse.data[0].responded_at,
      snapshotResponse2.data[0].responded_at,
    );
  }
}

