import { prepare_random_shopping_mall_admin_promotion_request } from "../../../prepare/prepare_random_shopping_mall_admin_promotion_request";

/**
 * Test that a seller can successfully retrieve the complete audit trail of snapshots
 * for their own administrator promotion request.
 *
 * Test Steps:
 * 1. Register a new seller account via /shoppingMall/auth/seller/join
 * 2. Submit an administrator promotion request via /shoppingMall/seller/admin-promotion-requests
 * 3. Retrieve the snapshots for the created request via the target endpoint
 * 4. Verify the response contains at least one snapshot with status 'pending'
 * 5. Verify the snapshot includes correct actorType ('seller'), status, reason (null for pending),
 *    and createdAt timestamp
 * 6. Verify the snapshot's respondingSuperAdministrator is null (since pending requests have
 *    no decision yet)
 */
export async function test_api_admin_promotion_request_snapshot_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a new seller account
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(sellerAuth);
  // 2. Submit an administrator promotion request
  const promotionRequest =
    await generate_random_shopping_mall_seller_admin_promotion_requests_create(
      sellerConnection,
      {
        body: {
          reason: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IShoppingMallAdminPromotionRequest.ICreate,
      },
    );
  typia.assert(promotionRequest);
  // 3. Retrieve the snapshots for the created request
  const snapshots =
    await api.functional.shoppingMall.seller.admin_promotion_requests.snapshots.index(
      sellerConnection,
      {
        requestId: promotionRequest.id,
        body: {
          page: 1,
          limit: 10,
          sort: "created_at",
          direction: "desc",
        } satisfies IShoppingMallAdminPromotionRequestSnapshot.IRequest,
      },
    );
  typia.assert(snapshots);
  // 4. Verify pagination metadata structure
  TestValidator.predicate(
    "current page is at least 1",
    snapshots.pagination.current >= 1,
  );
  TestValidator.predicate("limit is positive", snapshots.pagination.limit > 0);
  TestValidator.predicate(
    "records count is non-negative",
    snapshots.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pages count is non-negative",
    snapshots.pagination.pages >= 0,
  );
  // 5. Verify data array contains at least one snapshot
  TestValidator.predicate(
    "at least one snapshot exists",
    snapshots.data.length >= 1,
  );
  // 6. Verify the first snapshot (most recent) has correct values for pending request
  const firstSnapshot = snapshots.data[0]!;
  // Verify snapshot values for pending request
  TestValidator.equals(
    "actorType is seller",
    firstSnapshot.actorType,
    "seller",
  );
  TestValidator.equals("status is pending", firstSnapshot.status, "pending");
  TestValidator.equals(
    "reason is null for pending",
    firstSnapshot.reason,
    null,
  );
  TestValidator.equals(
    "respondingSuperAdministrator is null for pending",
    firstSnapshot.respondingSuperAdministrator,
    null,
  );
  // 7. Verify createdAt is a valid date-time string after request creation
  TestValidator.predicate(
    "createdAt is valid date-time",
    !isNaN(Date.parse(firstSnapshot.createdAt)),
  );
  const snapshotTime = new Date(firstSnapshot.createdAt).getTime();
  const requestTime = new Date(promotionRequest.created_at).getTime();
  TestValidator.predicate(
    "snapshot createdAt is after request creation",
    snapshotTime >= requestTime,
  );
}

