  );
  TestValidator.equals(
    "seller A page 2 - limit",
    sellerALowStockPage2.pagination.limit,
    limit,
  );
  TestValidator.equals(
    "seller A page 2 - total records",
    sellerALowStockPage2.pagination.records,
    8,
