    },
    _count: {
      id: true,
    },
  });
  return {
    averageRating: aggregate._avg.rating as
      | (number & tags.Minimum<1> & tags.Maximum<5>)
      | null,
    totalReviews: aggregate._count.id as number &
      tags.Type<"int32"> &
      tags.Minimum<0>,
  };
}

