import { TypedBody, TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IShoppingMallProduct } from "../../../../api/structures/IShoppingMallProduct";
import { SellerAuth } from "../../../../decorators/SellerAuth";
import { SellerPayload } from "../../../../decorators/payload/SellerPayload";
import { deleteShoppingMallSellerProductsProductId } from "../../../../providers/deleteShoppingMallSellerProductsProductId";
import { getShoppingMallSellerProductsProductIdAnalytics } from "../../../../providers/getShoppingMallSellerProductsProductIdAnalytics";
import { postShoppingMallSellerProducts } from "../../../../providers/postShoppingMallSellerProducts";
import { putShoppingMallSellerProductsProductId } from "../../../../providers/putShoppingMallSellerProductsProductId";

@Controller("/shoppingMall/seller/products")
export class ShoppingmallSellerProductsController {
  /**
   * Create a new product listing on the shopping mall platform.
   *
   * This operation allows sellers to create products for sale by providing the product name, description, category assignment, and base price. All four fields are required and the product cannot be created without them. The category can be either a main category or a subcategory.
   *
   * The product is automatically associated with the authenticated seller who created it and becomes their property. Upon successful creation, the product is immediately visible in search results and category listings.
   *
   * The system creates an initial product snapshot to preserve the product state at creation time for audit trail purposes.
   *
   * @param connection
   * @param body Product creation data with required fields for listing
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Create a new product record in the shopping_mall_products table.
   *
   * 1. Validate authenticated user is a seller with approved status
   * 2. Validate all required fields: name (non-empty string), description (non-empty string), category_id (valid UUID referencing shopping_mall_categories), base_price (positive number)
   * 3. Verify category_id exists in shopping_mall_categories table
   * 4. Set seller_id from authenticated seller's session
   * 5. Generate UUID for product id
   * 6. Set created_at and updated_at to current timestamp
   * 7. Set deleted_at to null
   * 8. Insert product record into shopping_mall_products table
   * 9. Create initial product snapshot in shopping_mall_product_snapshots table
   * 10. Return the created product entity
   *
   * Error handling:
   * - 400: Missing required fields, invalid category_id, non-positive base_price
   * - 403: User is not an approved seller
   * - 404: Category not found
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @SellerAuth()
    seller: SellerPayload,
    @TypedBody()
    body: IShoppingMallProduct.ICreate,
  ): Promise<IShoppingMallProduct> {
    try {
      return await postShoppingMallSellerProducts({
        seller,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update an existing product's information including name, description, category, and base price.
   *
   * This operation allows sellers to modify their own product listings. Sellers can update any combination of fields (name, description, category_id, base_price) - partial updates are supported. The category can be either a main category or a subcategory.
   *
   * The system validates that the product belongs to the requesting seller before allowing updates. Products that have been soft-deleted (deleted_at is not null) cannot be updated.
   *
   * Upon successful update, the product's updated_at timestamp is refreshed and a new snapshot is automatically created in the product snapshots table. This snapshot preserves the complete product state before modification for audit trail and dispute resolution purposes, as required by business rules.
   *
   * @param connection
   * @param productId Product UUID (global scope)
   * @param body Product update data with optional fields for partial updates
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Validate that the product exists and is not deleted (deleted_at is null). Verify that the requesting seller owns the product by checking seller_id matches the authenticated seller's ID. Check for pending order items with paid or shipped status referencing this product - reject if found. Check for pending cancellation or refund requests referencing this product's variants - reject if found. Update the product record with the provided name, description, category_id, and base_price. Set updated_at to current timestamp. Create a new snapshot record in shopping_mall_product_snapshots table capturing the complete product state before modification. Return the updated product entity with all fields including seller and category relationships.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":productId")
  public async update(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("productId")
    productId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IShoppingMallProduct.IUpdate,
  ): Promise<IShoppingMallProduct> {
    try {
      return await putShoppingMallSellerProductsProductId({
        seller,
        productId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Delete a product from the seller's catalog, removing it from search results and category listings.
   *
   * This operation soft-deletes the product by setting the deleted_at timestamp. The product becomes invisible to customers and cannot be purchased, but all data is preserved in the system. Product snapshots remain accessible to the seller and administrators for historical records and dispute resolution.
   *
   * Deletion is subject to business constraints: the product cannot be deleted if any variant has pending order items with paid or shipped status, or if there are any pending cancellation or refund requests for any variant. When deletion succeeds, all associated product variants are automatically cascade-deleted.
   *
   * @param connection
   * @param productId Product ID (UUID format, global scope)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Delete a product by productId after validating business constraints.
   *
   * 1. Verify the product exists and belongs to the authenticated seller (check seller_id matches).
   * 2. Check for pending order items: Query shopping_mall_order_items where shopping_mall_product_id = productId AND status IN ('paid', 'shipped'). If any exist, reject with 409 Conflict.
   * 3. Check for pending cancellation requests: Query shopping_mall_cancellation_requests joined with order_items where product matches AND status = 'pending'. If any exist, reject with 409 Conflict.
   * 4. Check for pending refund requests: Query shopping_mall_refund_requests joined with order_items where product matches AND status = 'pending'. If any exist, reject with 409 Conflict.
   * 5. If all validations pass, soft-delete the product by setting deleted_at to current timestamp.
   * 6. Cascade deletion automatically removes all shopping_mall_product_variants (onDelete: Cascade).
   * 7. Return 204 No Content on success.
   *
   * Error cases:
   * - 404 Not Found: Product does not exist or already deleted
   * - 403 Forbidden: Product does not belong to the authenticated seller
   * - 409 Conflict: Deletion blocked due to pending orders or requests
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":productId")
  public async erase(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("productId")
    productId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteShoppingMallSellerProductsProductId({
        seller,
        productId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve comprehensive analytics and performance metrics for a specific product.
   *
   * This operation aggregates sales data from the shopping_mall_order_items table and review statistics from the shopping_mall_reviews table to provide sellers and administrators with insights into product performance. The analytics include total units sold, revenue generated, review count, and average rating.
   *
   * Sellers can access analytics for their own products to monitor sales performance and customer satisfaction. Administrators can access analytics for any product on the platform for oversight and reporting purposes. The data is calculated from historical order items and review records associated with the product.
   *
   * Product analytics help sellers make informed decisions about inventory management, pricing strategies, and product improvements. The metrics reflect all transactions and reviews associated with the product throughout its lifecycle, excluding cancelled and refunded order items from sales calculations.
   *
   * @param connection
   * @param productId Product identifier (UUID format)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Query shopping_mall_products table to verify product exists and retrieve basic product information.
   *
   * For sales metrics:
   * - Aggregate orderItems where shopping_mall_product_id = productId
   * - Sum quantity across all order items for total units sold
   * - Sum (quantity * price) for total revenue
   * - Filter by status to exclude cancelled/refunded items if business rules require
   *
   * For review metrics:
   * - Aggregate reviews where product_id = productId and deleted_at IS NULL
   * - Count total reviews
   * - Calculate average rating (AVG of rating field)
   * - Handle case where no reviews exist (return 0 or null)
   *
   * Authorization: Verify requesting user is either the product's seller or an administrator.
   *
   * Return IShoppingMallProduct.IAnalytics with all computed metrics.
   *
   * Edge cases:
   * - Product not found: return 404
   * - Product deleted: return 404 or include in analytics with deleted flag
   * - No order items: return 0 for sales metrics
   * - No reviews: return 0 for review count, null or 0 for average rating
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":productId/analytics")
  public async analytics(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("productId")
    productId: string & tags.Format<"uuid">,
  ): Promise<IShoppingMallProduct.IAnalytic> {
    try {
      return await getShoppingMallSellerProductsProductIdAnalytics({
        seller,
        productId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

